-- 001_initial_schema.sql
-- Phase 0: normative reference schema, verbatim from docs/45_STORAGE_SCHEMA.sql.
-- PostgreSQL 16+.
-- MANDATORY follow-up (application migrations, before any tenant data):
--   * RLS tenant policies on ALL tenant tables, with FORCE ROW LEVEL SECURITY;
--   * DB permissions/triggers preventing UPDATE/DELETE on events and settled ledger;
--   * remaining domain-specific tables from capability inventory + migration tests.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL);
CREATE TABLE actors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), subject text NOT NULL, UNIQUE(tenant_id,subject));
CREATE TABLE projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), name text NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE works(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), project_id uuid NOT NULL, created_by uuid NOT NULL REFERENCES actors(id), objective text NOT NULL, state text NOT NULL DEFAULT 'open', version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,project_id) REFERENCES projects(tenant_id,id));
CREATE TABLE executions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, work_id uuid NOT NULL, parent_execution_id uuid, state text NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','awaiting_approval','verifying','needs_reconciliation','cancelling','completed','failed','cancelled','budget_exhausted')), version bigint NOT NULL DEFAULT 0, budget_cap_usd numeric(18,6) NOT NULL CHECK(budget_cap_usd>=0), reserved_usd numeric(18,6) NOT NULL DEFAULT 0 CHECK(reserved_usd>=0), spent_usd numeric(18,6) NOT NULL DEFAULT 0 CHECK(spent_usd>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,work_id) REFERENCES works(tenant_id,id), FOREIGN KEY(tenant_id,parent_execution_id) REFERENCES executions(tenant_id,id), CHECK(reserved_usd+spent_usd<=budget_cap_usd));
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, execution_id uuid NOT NULL, sequence bigint NOT NULL, type text NOT NULL, payload jsonb NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,execution_id,sequence), FOREIGN KEY(tenant_id,execution_id) REFERENCES executions(tenant_id,id));
CREATE TABLE outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL UNIQUE REFERENCES events(id), published_at timestamptz, attempts integer NOT NULL DEFAULT 0);
CREATE TABLE idempotency_keys(tenant_id uuid NOT NULL REFERENCES tenants(id), actor_id uuid NOT NULL REFERENCES actors(id), route text NOT NULL, key text NOT NULL, request_hash text NOT NULL, response_json jsonb, response_status integer, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,actor_id,route,key));
CREATE TABLE agent_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, execution_id uuid NOT NULL, state text NOT NULL, step_count integer NOT NULL DEFAULT 0, checkpoint_ref text, version bigint NOT NULL DEFAULT 0, UNIQUE(tenant_id,execution_id), FOREIGN KEY(tenant_id,execution_id) REFERENCES executions(tenant_id,id));
CREATE TABLE worker_leases(tenant_id uuid NOT NULL, execution_id uuid NOT NULL, worker_id text NOT NULL, fence bigint NOT NULL, expires_at timestamptz NOT NULL, PRIMARY KEY(tenant_id,execution_id), FOREIGN KEY(tenant_id,execution_id) REFERENCES executions(tenant_id,id));
CREATE TABLE approvals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, execution_id uuid NOT NULL, reviewer_id uuid, action_digest char(64) NOT NULL, policy_version text NOT NULL, base_sha char(40) NOT NULL, patch_sha char(64) NOT NULL, evidence_digest char(64) NOT NULL, expires_at timestamptz NOT NULL, decision text NOT NULL DEFAULT 'pending' CHECK(decision IN ('pending','approved','denied','expired')), consumed_at timestamptz, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,execution_id) REFERENCES executions(tenant_id,id));
CREATE TABLE external_effects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, execution_id uuid NOT NULL, provider text NOT NULL, provider_key text, action_digest char(64) NOT NULL, status text NOT NULL CHECK(status IN ('prepared','dispatched','confirmed','unknown','rejected','manual_review')), fence bigint NOT NULL, response_digest char(64), UNIQUE(tenant_id,provider,provider_key), FOREIGN KEY(tenant_id,execution_id) REFERENCES executions(tenant_id,id));
CREATE TABLE budget_ledger(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, execution_id uuid NOT NULL, provider_request_id text, kind text NOT NULL CHECK(kind IN ('reserve','settle','refund','transfer')), amount_usd numeric(18,6) NOT NULL CHECK(amount_usd>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,provider_request_id), FOREIGN KEY(tenant_id,execution_id) REFERENCES executions(tenant_id,id));
CREATE TABLE artifacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL, execution_id uuid NOT NULL, object_key text NOT NULL, sha256 char(64) NOT NULL, media_type text NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,execution_id) REFERENCES executions(tenant_id,id));
CREATE TABLE "references"(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), kind text NOT NULL, target_id uuid NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE "relations"(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenants(id), from_ref uuid NOT NULL, to_ref uuid NOT NULL, kind text NOT NULL, FOREIGN KEY(tenant_id,from_ref) REFERENCES "references"(tenant_id,id), FOREIGN KEY(tenant_id,to_ref) REFERENCES "references"(tenant_id,id));
CREATE INDEX events_by_execution ON events(tenant_id,execution_id,sequence);
CREATE INDEX execution_by_work ON executions(tenant_id,work_id,created_at);
CREATE INDEX lease_expiry ON worker_leases(expires_at);
-- MUST implement RLS tenant policies on ALL tenant tables, with FORCE ROW LEVEL SECURITY;
-- MUST implement DB permissions/triggers preventing UPDATE/DELETE on events and settled ledger;
-- MUST add remaining domain-specific tables from capability inventory and migration tests.